-------------------------
# JetTheme Css Variable #
-------------------------

<Group description="_Main Color">
<Variable name="keycolor" description="Main Color" type="color" default="#f67938" value="#f67938"/>
<Variable name="body.background" description="Body Background Color" type="color" default="#ffffff" value="#ffffff"/>
<Variable name="body.text.color" description="Font Color" type="color" default="#686868" value="#686868"/>
<Variable name="posts.title.color" description="Heading Color" type="color" default="#343a40" value="#000000"/>
<Variable name="body.link.color" description="Link Color" type="color" default="$(keycolor)" value="#f67938"/>
<Variable name="body.hover.color" description="Link Hover" type="color" default="#f46013" value="#f46013"/>
<Variable name="border.color" description="Border Color" type="color" default="#efefef" value="#efefef"/>
<Variable name="posts.text.color" description="Blockquote Border Color" type="color" default="$(keycolor)" value="#f67938"/>
</Group>

<Group description="_Typography">
<Variable name="body.text" description="Body Font" type="font" default="normal normal 16px system-ui,-apple-system,Segoe UI,Helvetica Neue,Arial,Noto Sans,Liberation Sans,sans-serif,Apple Color Emoji,Segoe UI Emoji,Segoe UI Symbol,Noto Color Emoji" value="normal normal 16px system-ui,-apple-system,Segoe UI,Helvetica Neue,Arial,Noto Sans,Liberation Sans,sans-serif,Apple Color Emoji,Segoe UI Emoji,Segoe UI Symbol,Noto Color Emoji"/>
<Variable name="posts.title" description="Heading Font" type="font" default="normal bold 40px var(--bs-font-sans-serif)" value="normal bold 40px var(--bs-font-sans-serif)"/>
<Variable name="title.h2" description="H2 Size" type="length" default="26px" min="12px" max="50px" value="26px"/>
<Variable name="title.h3" description="H3 Size" type="length" default="22px" min="12px" max="50px" value="22px"/>
<Variable name="title.h4" description="H4 Size" type="length" default="20px" min="12px" max="50px" value="20px"/>
<Variable name="title.h5" description="H5 Size" type="length" default="18px" min="12px" max="50px" value="18px"/>
<Variable name="title.h6" description="H6 Size" type="length" default="16px" min="12px" max="50px" value="16px"/>
</Group> 

<Group description="_Logo">
<Variable name="logo.width" description="Logo Max Width" type="length" default="200px" min="50px" max="500px" value="200px"/>
<Variable name="logo.width.mobile" description="Logo Max Width (mobile)" type="length" default="150px" min="50px" max="500px" value="150px"/>
</Group>

<Group description="_Header Color">
<Variable name="header.bg" description="Background" type="color" default="#ffffff" value="#ffffff"/>
<Variable name="header.color" description="Font Color " type="color" default="#686868" value="#686868"/>
<Variable name="header.border" description="Border Color" type="color" default="#efefef" value="#efefef"/>
</Group>

<Group description="_Menu">
<Variable name="tabs.font" description="Menu Font" type="font" default="normal bold 16px var(--bs-font-sans-serif)" value="normal bold 16px var(--bs-font-sans-serif)"/>
<Variable name="tabs.color" description="Font Color" type="color" default="$(body.text.color)" value="#686868"/>
<Variable name="tabs.hover" description="Font Hover" type="color" default="$(keycolor)" value="#f67938"/>
<Variable name="tabs.selected.color" description="Font Selected" type="color" default="$(keycolor)" value="#f67938"/>
</Group>

<Group description="_Dropdown Menu">
<Variable name="dropdown.font" description="Font Size" type="length" default="16px" min="12px" max="50px" value="15px"/>
<Variable name="dropdown.bg" description="Background Color" type="color" default="$(body.text.color)" value="#ffffff"/>
<Variable name="dropdown.color" description="Font Color" type="color" default="$(keycolor)" value="#686868"/>
<Variable name="dropdown.hover" description="Font Hover" type="color" default="$(keycolor)" value="#f67938"/>
<Variable name="dropdown.selected" description="Dropdown Selected Color" type="color" default="$(keycolor)" value="#f67938"/>
</Group>

<Group description="_Footer Color">
<Variable name="footer.bg" description="Background Color" type="color" default="#212529" value="#212529"/>
<Variable name="footer.color" description="Font Color" type="color" default="#9fa6ad" value="#9fa6ad"/>
<Variable name="footer.link" description="Link Color" type="color" default="#9fa6ad" value="#9fa6ad"/>
<Variable name="footer.border" description="Border Color" type="color" default="#323539" value="#323539"/>
</Group>

<Group description="_Socket Color">
<Variable name="socket.bg" description="Background Color" type="color" default="#09080c" value="#09080c"/>
<Variable name="socket.color" description="Font Color" type="color" default="#9fa6ad" value="#9fa6ad"/>
</Group>

<Group description="_Button">
<Variable name="posts.icons.color" description="Button Color" type="color" default="$(keycolor)" value="#f67938"/>
<Variable name="labels.background.color" description="Button Hover"  type="color"  default="#f46013" value="#f46013"/>
</Group>

<Group description="_Comment Form">
<Variable name="body.text.font" description="Font" type="font" default="normal normal 14px system-ui,-apple-system,Segoe UI,Helvetica Neue,Arial,Noto Sans,Liberation Sans,sans-serif,Apple Color Emoji,Segoe UI Emoji,Segoe UI Symbol,Noto Color Emoji" value="normal normal 14px system-ui,-apple-system,Segoe UI,Helvetica Neue,Arial,Noto Sans,Liberation Sans,sans-serif,Apple Color Emoji,Segoe UI Emoji,Segoe UI Symbol,Noto Color Emoji"/>
<Variable name="posts.background.color" description="Background" type="color" default="transparent" value="rgba(0,0,0,0)"/>
</Group>
*/
/*
-----------------------------------------------
JetTheme Blogger Template
Name		: JetTheme Core
Version		: 2.9
Designer	: jettheme
URL			: www.jettheme.com
-----------------------------------------------
*/

/* ======================================================
   PART A: ORIGINAL JETTHEME CSS (unchanged)
   ====================================================== */
:root {
--bs-font-sans-serif: $(body.text.family);
--bs-body-bg: $(body.background);
--bs-body-color: $(body.text.color);
--jt-primary: $(keycolor);
--jt-heading-color: $(posts.title.color);
--jt-heading-link: $(posts.title.color);
--jt-heading-hover: $(keycolor);
--jt-link-color: $(body.link.color);
--jt-link-hover: $(body.hover.color);
--jt-blockquote: $(posts.text.color);
--jt-btn-primary: $(posts.icons.color);
--jt-btn-primary-hover: $(labels.background.color);
--jt-btn-light-hover: $(posts.title.color);
--jt-border-light: $(border.color);
--jt-bg-light: #f3f7f9;
--jt-archive-bg: #ffffff;
--jt-nav-color: $(tabs.color);
--jt-nav-hover: $(tabs.hover);
--jt-nav-selected: $(tabs.selected.color);
--jt-dropdown-bg: $(dropdown.bg);
--jt-dropdown-color: $(dropdown.color);
--jt-dropdown-hover: $(dropdown.hover);
--jt-dropdown-selected: $(dropdown.selected);
--jt-header-bg: $(header.bg);
--jt-header-color: $(header.color);
--jt-header-border: $(header.border);
--jt-footer-bg: $(footer.bg);
--jt-footer-color: $(footer.color);
--jt-footer-link: $(footer.link);
--jt-footer-border: $(footer.border);
--jt-socket-bg: $(socket.bg);
--jt-socket-color: $(socket.color);
}
.dark-mode {
--bs-body-bg: hsl(210, 11%, 15%);
--bs-body-color: hsl(210, 11%, 80%);
--jt-heading-color: hsl(210, 11%, 80%);
--jt-heading-link: hsl(210, 11%, 80%);
--jt-btn-light-hover: hsl(210, 11%, 85%);
--jt-border-light: hsl(210, 11%, 20%);
--jt-bg-light: hsl(210, 11%, 20%);
--jt-archive-bg: hsl(210, 11%, 17%);
--jt-nav-color: hsl(210, 11%, 70%);
--jt-dropdown-bg: hsl(210, 11%, 18%);
--jt-dropdown-color: hsl(210, 11%, 70%);
--jt-header-bg: hsl(210, 11%, 15%);
--jt-header-color: hsl(210, 11%, 80%);
--jt-header-border: hsl(210, 11%, 20%);
--jt-footer-bg: hsl(210, 11%, 15%);
--jt-footer-color: hsl(210, 11%, 80%);
--jt-footer-border: hsl(210, 11%, 20%);
--jt-socket-bg: hsl(210, 11%, 17%);
--jt-socket-color: hsl(210, 11%, 80%);
}

body {
font: $(body.text);
color: var(--bs-body-color);
background-color: var(--bs-body-bg);
line-height: 1.5;
-webkit-font-smoothing: antialiased;
-moz-osx-font-smoothing: grayscale;
text-rendering: optimizeLegibility;
}
.d-block {
display:none;
}
.h1,.h2,.h3,.h4,.h5,.h6,
h1,h2,h3,h4,h5,h6 {
font: $(posts.title);
}
a {
transition-property: background-color, border-color, color, fill, stroke;
transition-timing-function: cubic-bezier(0.4, 0, 0.2, 1);
transition-duration: .3s;
text-decoration: none;
color: var(--jt-link-color);
}
a:hover {
color: var(--jt-link-hover);
}
.fs-7 {
font-size: 0.875rem;
}
.fs-8 {
font-size: 0.75rem;
}
.fs-9 {
font-size: 0.7rem;
}
.btn{
box-shadow: none !important
}
.btn-sm {
min-width: 32px;
min-height: 32px;
}
img,
svg,
iframe {
max-width:100%
}
img {
height:auto;
object-fit:cover;
}
label {
cursor: pointer;
}
.visually-hidden {
position: unset !important;
}
.form-control:focus {
box-shadow: none;
border-color: var(--jt-primary);
}
.form-control::placeholder {
opacity: .5;
}
.dropdown-toggle::after {
border-width: 0.25em 0.25em 0;
}
.dropdown-menu {
margin: 0;
padding: 0;
}
.px-3 {
padding-right: 1rem;
padding-left: 1rem;
}
.ratio:before{
content: none;
}
.ratio-1x1 {
padding-bottom: 100%;
}
.ratio-4x3 {
padding-bottom: 75%;
}
.ratio-16x9 {
padding-bottom: 56.25%;
}
.ratio-21x9 {
padding-bottom: 43%;
}
.object-cover {
object-fit: cover;
}
.jt-text-primary,
.hover-text-primary:hover,
input:checked ~ .check-text-primary {
color: var(--jt-primary)!important
}
.jt-btn-primary,
.jt-btn-outline-primary:hover {
color: #fff;
background-color: var(--jt-btn-primary);
border-color: var(--jt-btn-primary);
}
.jt-btn-light {
color: var(--bs-body-color);
background-color: var(--jt-bg-light);
border-color: var(--jt-bg-light);
}
.jt-btn-light:hover {
color: var(--jt-btn-light-hover);
}
.jt-btn-primary:hover,
.hover-btn-primary:hover,
input:checked + .jt-btn-outline-primary {
color: #fff !important;
background-color: var(--jt-btn-primary-hover)!important;
border-color: var(--jt-btn-primary-hover)!important
}
.jt-btn-outline-primary {
color: var(--jt-btn-primary);
border-color: var(--jt-btn-primary);
}
.jt-bg-primary {
background-color: var(--jt-primary)
}
.jt-bg-light {
background-color: var(--jt-bg-light)
}
.bg-archive {
background-color: var(--jt-archive-bg)
}
.jt-border-light {
border-color: var(--jt-border-light)!important;
}
input:checked ~ .d-block-check {
display: block !important;
}
input:checked ~ .d-none-check {
display: none !important;
}
.dropdown-menu,
.accordion-item,
.accordion-header {
background-color: var(--bs-body-bg);
color: var(--bs-body-color);
border-color: var(--jt-border-light);
}
.lazyload {
transition-property: opacity;
transition-timing-function: cubic-bezier(0.4, 0, 0.2, 1);
transition-duration: .3s;
opacity: 0;
}
.lazyload.loaded {
opacity: 1;
}

/* JetTheme Style */

pre {
background-color: var(--jt-bg-light);
margin-bottom: 1rem;
padding: 1rem;
font-size: 0.75rem;
}
blockquote {
border-left:  5px solid var(--jt-blockquote);
color: inherit;
font-size: 1.125rem;
margin-bottom: 1.5rem;
margin-top: 1.5rem;
padding-left: 1rem;
}
.header-animate.header-hidden {
transform: translateY(-100%);
box-shadow: none !important;
}
#header {
background-color: var(--jt-header-bg);
color: var(--jt-header-color);
transition-property: transform;
transition-timing-function: cubic-bezier(0.4, 0, 0.2, 1);
transition-duration: .3s;
min-height: 50px;
border-bottom: 1px solid var(--jt-header-border);
}
.header-social {
border-right: 1px solid var(--jt-header-border);
}
.jt-icon {
display: inline-block;
height: 1em;
vertical-align: -0.15em;
width: 1em;
fill:none;
stroke:currentColor;
stroke-linecap:round;
stroke-linejoin:round;
stroke-width:2;
}
.jt-icon-center {
font-family: sans-serif;
}
.icon-dark,
.dark-mode .icon-light {
display: none;
}
.dark-mode .icon-dark {
display: block;
}
#dark-toggler,
#search-toggler,
#navbar-toggler {
line-height: 1;
}
#dark-toggler {
font-size: 17px;
}
#footer {
background-color: var(--jt-footer-bg);
color: var(--jt-footer-color);
border-top: 1px solid var(--jt-footer-border);
}
#socket {
background-color: var(--jt-socket-bg);
color: var(--jt-socket-color);
}
#navbar {
z-index: 9999;
}
#navbar .menu-item {
position: relative;
}
#navbar .nav-link {
min-height: 40px;
}
#navbar .dropdown-toggle {
cursor: pointer;
align-items: center;
display: flex;
}
#navbar.d-block,
#navbar .dropdown-menu,
#navbar .nav-link,
#navbar .dropdown-toggle {
-webkit-transition: .3s;
-ms-transition: .3s;
-o-transition: .3s;
transition: .3s;
}
#navbar .navbar-nav > .menu-item > .nav-link {
font: $(tabs.font);
line-height: 1.5;
color: var(--jt-nav-color);
}
#navbar .navbar-nav > .menu-item:hover > .nav-link,
#navbar .navbar-nav > .menu-item:hover > .dropdown-toggle {
color: var(--jt-nav-hover);
}
#navbar .navbar-nav > .menu-item > .nav-link.active,
#navbar .navbar-nav > .menu-item > .active ~ .dropdown-toggle {
color: var(--jt-nav-selected);
}
.logo-wrap {
width: $(logo.width);
}
#search-header .dropdown-menu {
background-color:var(--jt-dropdown-bg);
color: var(--jt-dropdown-color);
border-color: var(--jt-header-border);
min-width: 300px;
right:0;
top:100%
}
.blog-admin {
display: none;
}
#pagination li + li {
margin-left: 5px;
}
.no-items {
display: none;
}
.feature-image,
.separator,
.tr-caption-container {
margin-bottom: 1rem;
}
.tr-caption-container {
width: 100%;
}
.separator a,
.tr-caption-container a {
margin: 0 !important;
padding: 0 !important;
}
.tr-caption {
font-size: 12px;
font-style: italic;
}
.widget:last-child {
margin-bottom: 0 !important;
}
#post-body .widget {
margin-top: 1.5rem;
}
.item-title {
color: var(--jt-heading-link);
}
.item-title:hover {
color: var(--jt-heading-hover);
}
#comment-editor{
width:100%
}
#primary .widget-title {
font-weight: 300;
text-transform: uppercase;
}
#footer .widget-title {
text-transform: uppercase;
}
#footer .widget-title,
#sidebar .widget-title {
font-size: 13px !important;
}
#footer .widget-title:after {
content: "";
display: block;
width: 50px;
border-bottom: 2px solid var(--jt-primary);
margin-top: 10px;
}
#primary .widget-title > span {
background-color: var(--bs-body-bg);
padding-right: 5px;
position: relative;
}
#main .widget-title:before,
#sidebar .widget-title:before {
background-color:  var(--jt-bg-light);
content: "";
height: 1px;
display: block;
position: absolute;
top: 50%;
transform: translateY(-50%);
width: 100%;
}
#main .widget-title:before {
border-right: 30px solid var(--jt-primary);
height: 5px;
}
.send-success:not(.loading) .contact-form-msg,
.send-error:not(.loading) .contact-form-msg {
display:block !important;
}
.send-success .contact-form-msg{
border-color: rgba(25,135,84,.3) !important;
}
.send-error .contact-form-msg{
border-color: rgba(255,193,7,.3) !important;
}
.send-success .contact-form-msg:before{
content: attr(data-success);
}
.send-error .contact-form-msg:before{
content: attr(data-error);
}
hr.example-ads:before {
content: "Advertisement here";
}
hr.example-ads {
background-color: var(--jt-bg-light);
border-radius: 0.25rem;
font-size: 0.875rem;
height: auto;
margin: 0;
opacity: 1;
padding: 1.5rem 0;
text-align: center;
}
body > .google-auto-placed {
margin: 0 auto 1.5rem;
max-width: 1108px;
}
.google-auto-placed > ins {
margin: 0 !important;
}


/* TYPOGRAPY */

.h1,h1{font-size:calc(1.375rem + 1.5vw)}
.h2,h2{font-size:calc(1.325rem + .9vw)}
.h3,h3{font-size:calc(1.3rem + .6vw)}
.h4,h4{font-size:calc(1.275rem + .3vw)}
.h5,h5{font-size:$(title.h5)}
.h6,h6{font-size:$(title.h6)}

.entry-title {
color: var(--jt-heading-color);
}
.entry-text h1,
.entry-text h2,
.entry-text h3,
.entry-text h4,
.entry-text h5,
.entry-text h6 {
color: var(--jt-heading-color);
padding-top: 1em;
margin-bottom: 1rem;
}

.entry-text li {
margin-bottom: 0.5rem;
}

/* Responsive Style */

@media (min-width: 576px) {
.ratio-sm-4x3 {
padding-bottom: 75%;
}
.ratio-sm-16x9 {
padding-bottom: 56.25%;
}
.border-sm-end {
border-right-width: 1px !important;
border-right-style: solid;
}
#post-pager .next-page {
border-left: 1px solid;
}
}
@media (min-width: 768px) {
.position-md-relative {
position: relative;
}
.border-md-end {
border-right-width: 1px !important;
border-right-style: solid;
}
}
@media (min-width: 992px) {
.d-lg-flex {
display: flex;
}
.col-lg-4 {
flex: 0 0 auto;
width: 33.33333333%;
}
.col-lg-8 {
flex: 0 0 auto;
width: 66.66666667%;
}
.border-lg-end {
border-right-width: 1px !important;
border-right-style: solid;
}
#navbar .navbar-nav > .menu-item {
display: flex;
}
#navbar .dropdown-menu {
background-color:var(--jt-dropdown-bg);
border-color: var(--jt-header-border);
margin-top: -10px;
display: block;
opacity: 0;
visibility: hidden;
pointer-events: none;
box-shadow: 5px 10px 10px -5px rgba(0, 0, 0, 0.14);
top:100%;
min-width: 150px;
}
#navbar .dropdown-menu .nav-link {
padding-right: 20px;
font-size: $(dropdown.font);
color: var(--jt-dropdown-color);
}
#navbar .dropdown-menu .dropdown-toggle {
position: absolute;
right: 10px;
top: 20px;
}
#navbar .dropdown-menu .dropdown-menu {
left: 100%;
top: -1px;
}
#navbar .dropdown-menu .menu-item:hover > .nav-link,
#navbar .dropdown-menu .menu-item:hover > .dropdown-toggle {
color:  var(--jt-dropdown-hover);
}
#navbar .dropdown-menu .menu-item > .nav-link.active,
#navbar .dropdown-menu .menu-item > .active ~ .dropdown-toggle {
color:  var(--jt-dropdown-selected);
}
#navbar .menu-item:hover > .dropdown-menu {
opacity: 1;
visibility: visible;
pointer-events: unset;
margin: 0;
}
#navbar .navbar-nav > .menu-item > .nav-link {
padding: 1.5rem 1.2rem;
white-space:nowrap;
}
#navbar .navbar-nav > .menu-item > .dropdown-toggle {
bottom: 0;
pointer-events: none;
position: absolute;
right: 5px;
top: 3px;
}
#sidebar {
border-left: 1px solid var(--jt-border-light);
}
#footer-widget .widget {
margin-bottom: 0 !important;
}
}
@media (min-width: 1200px){
.container {
max-width: 1140px;
}
.h1,h1{font-size:$(posts.title.size)}
.h2,h2{font-size:$(title.h2)}
.h3,h3{font-size:$(title.h3)}
.h4,h4{font-size:$(title.h4)}
}
@media (min-width: 1400px) {
.container {
max-width: 1320px;
}
}
@media (max-width: 991.98px) {
input:checked ~ .dropdown-menu {
display: block;
}
input:checked + .dropdown-toggle {
color: var(--jt-dropdown-selected);
}
.logo-wrap {
width: $(logo.width.mobile);
}
#search-header .dropdown-menu{
width: 100%;
}
#navbar {
background-color: var(--jt-header-bg);
padding-top: 70px;
padding-bottom: 30px;
position: fixed;
left: 0;
right: 0;
top: 0;
bottom: 0;
width: auto;
}
#navbar.d-block {
opacity: 0;
transform: translateX(-20%);
}
#navbar.show {
transform: translateX(0);
opacity: 1;
}
#navbar .navbar-nav {
max-height: 100%;
overflow-y: auto;
}
#navbar-toggle:checked ~ #header-main #navbar {
display:block;
}
#navbar .nav-link {
border-bottom: 1px solid var(--jt-header-border);
font-size: 16px !important;
color: var(--jt-dropdown-color);
}
#navbar .menu-item:hover > .nav-link {
color: var(--jt-dropdown-hover);
}
#navbar .active > .nav-link {
color: var(--jt-dropdown-selected);
}
#navbar .dropdown-toggle {
border-left: 1px solid var(--jt-header-border);
height: 2.5rem;
padding: 0 1rem;
position: absolute;
right: 0;
top: 0;
}
#navbar .dropdown-menu {
background-color: var(--jt-dropdown-bg);
border: none;
padding-left: 10px;
}
#sidebar {
border-top: 1px solid var(--jt-border-light);
}
}
@media (max-width: 575.98px) {
.feature-posts .item-thumbnail {
margin-bottom: -150px;
}
.feature-posts .item-thumbnail a {
border-radius: 0 !important;
box-shadow: none !important;
padding-bottom: 75%;
}
.feature-posts .item-content {
background-color: var(--bs-body-bg);
border: 5px solid;
border-radius: 0.25rem;
}
#post-pager .prev-page + .next-page {
border-top: 1px solid;
}
.full-width,
.px-3 .google-auto-placed {
margin-left: -1rem;
margin-right: -1rem;
width: auto !important;
}
#footer-widget .widget {
padding-left: 3rem;
padding-right: 3rem;
}
}

/* ======================================================
   PART B: GLASSMORPHISM DESIGN SYSTEM (new)
   Keeps every original color variable; only adds effects.
   NOTE: dark-mode tokens are declared AFTER :root on purpose.
   ====================================================== */
:root {
--glass-bg: rgba(255,255,255,.55);
--glass-bg-soft: rgba(255,255,255,.38);
--glass-bg-strong: rgba(255,255,255,.80);
--glass-header: rgba(255,255,255,.62);
--glass-border: rgba(255,255,255,.70);
--glass-ring: rgba(246,121,56,.14);
--glass-shadow: 0 8px 32px rgba(0,0,0,.10);
--glass-shadow-hover: 0 14px 40px rgba(246,121,56,.25);
--glass-filter: blur(15px) saturate(180%);
--glass-radius: 20px;
--glass-radius-sm: 14px;
--glow-a: rgba(246,121,56,.30);
--glow-b: rgba(246,121,56,.16);
--glow-c: rgba(255,176,110,.22);
}
.dark-mode {
--glass-bg: rgba(30,30,35,.55);
--glass-bg-soft: rgba(30,30,35,.40);
--glass-bg-strong: rgba(30,30,35,.82);
--glass-header: rgba(24,24,29,.60);
--glass-border: rgba(255,255,255,.10);
--glass-ring: rgba(246,121,56,.20);
--glass-shadow: 0 8px 32px rgba(0,0,0,.40);
--glass-shadow-hover: 0 14px 40px rgba(246,121,56,.30);
--glow-a: rgba(246,121,56,.22);
--glow-b: rgba(246,121,56,.12);
--glow-c: rgba(255,140,70,.12);
}

/* B1. Page background: orange glow gradient (light + dark) */
body {
background-image:
radial-gradient(60rem 40rem at 8% -8%, var(--glow-a), transparent 60%),
radial-gradient(48rem 34rem at 100% 8%, var(--glow-b), transparent 55%),
radial-gradient(46rem 30rem at 50% 112%, var(--glow-c), transparent 60%);
background-attachment: fixed;
background-repeat: no-repeat;
min-height: 100vh;
}

/* B2. Shared glass surface */
.glass,
.glass-box,
.bg-archive,
#sidebar .widget,
#single-content,
#page-content,
#toc-post,
.comments,
.post-author,
.accordion-item,
.key-takeaways {
background: var(--glass-bg) !important;
-webkit-backdrop-filter: var(--glass-filter);
backdrop-filter: var(--glass-filter);
border: 1px solid var(--glass-border) !important;
border-radius: var(--glass-radius) !important;
box-shadow: var(--glass-shadow), 0 0 0 1px var(--glass-ring);
}
@supports not ((backdrop-filter: blur(1px)) or (-webkit-backdrop-filter: blur(1px))) {
.glass,.glass-box,.bg-archive,#sidebar .widget,#single-content,#page-content,#toc-post,.comments,.post-author,.accordion-item,.key-takeaways {
background: var(--glass-bg-strong) !important;
}
}

/* B3. Header: glass sticky navbar.
   Blur lives on a pseudo-element so the fixed mobile menu keeps working
   (backdrop-filter on #header itself would trap position:fixed children). */
#header {
position: sticky;
top: 0;
z-index: 1030;
background: transparent !important;
isolation: isolate;
border-bottom: 1px solid var(--glass-border);
box-shadow: 0 4px 24px rgba(0,0,0,.06);
}
#header::before {
content: "";
position: absolute;
inset: 0;
z-index: -1;
background: var(--glass-header);
-webkit-backdrop-filter: blur(18px) saturate(180%);
backdrop-filter: blur(18px) saturate(180%);
}
#navbar .dropdown-menu,
#search-header .dropdown-menu {
background: var(--glass-bg-strong) !important;
-webkit-backdrop-filter: var(--glass-filter);
backdrop-filter: var(--glass-filter);
border: 1px solid var(--glass-border);
border-radius: var(--glass-radius-sm);
overflow: hidden;
}

/* B4. Post cards (archive / home) */
.item-post .bg-archive,
.bg-archive {
transition: transform .35s cubic-bezier(.2,.8,.2,1), box-shadow .35s ease, border-color .35s ease;
will-change: transform;
}
.bg-archive:hover {
transform: translateY(-4px) scale(1.012);
box-shadow: var(--glass-shadow-hover), 0 0 0 1px rgba(246,121,56,.35);
border-color: rgba(246,121,56,.45) !important;
}
.bg-archive .item-thumbnail img {
transition: transform .5s ease;
}
.bg-archive:hover .item-thumbnail img {
transform: scale(1.05);
}
.feature-posts .item-thumbnail a {
border-radius: var(--glass-radius) !important;
}
.feature-posts .item-content {
background: var(--glass-bg-strong);
}

/* B5. Sidebar widgets as glass cards */
#sidebar {
border-left: 0 !important;
border-top: 0 !important;
}
#sidebar .widget {
padding: 1.25rem;
margin-bottom: 1.25rem !important;
}
#sidebar .widget-title:before { display: none; }
#sidebar .widget-title > span,
#primary #sidebar .widget-title > span {
background: transparent;
padding: 0 0 6px;
border-bottom: 3px solid var(--jt-primary);
}
#main .widget-title > span {
background: var(--glass-bg-strong);
padding: 4px 14px;
border-radius: 999px;
}

/* B6. Single post / page / comments */
#single-content,
#page-content {
padding: clamp(1.1rem, 3vw, 2.25rem);
}
.comments { padding: 1.25rem; }
.comment-content {
background: var(--glass-bg-soft) !important;
border: 1px solid var(--glass-border);
border-radius: var(--glass-radius-sm) !important;
}
.entry-text img,
.entry-text .separator img {
border-radius: var(--glass-radius-sm);
}
.entry-text table {
display: block;
overflow-x: auto;
max-width: 100%;
border-collapse: separate;
border-spacing: 0;
border: 1px solid var(--glass-border);
border-radius: var(--glass-radius-sm);
background: var(--glass-bg-soft);
}
.entry-text th, .entry-text td { padding: .6rem .9rem; }
blockquote {
background: var(--glass-bg-soft);
-webkit-backdrop-filter: var(--glass-filter);
backdrop-filter: var(--glass-filter);
border-radius: 0 var(--glass-radius-sm) var(--glass-radius-sm) 0;
padding: 1rem 1.25rem;
}
pre {
background: var(--glass-bg-soft);
border: 1px solid var(--glass-border);
border-radius: var(--glass-radius-sm);
overflow-x: auto;
}
#post-pager {
background: var(--glass-bg-soft);
border-radius: var(--glass-radius-sm);
overflow: hidden;
}
#toc-post { max-width: 100%; }

/* B7. Buttons: glass, solid keycolor on hover */
.jt-btn-light {
background: var(--glass-bg-soft) !important;
border: 1px solid var(--glass-border) !important;
-webkit-backdrop-filter: var(--glass-filter);
backdrop-filter: var(--glass-filter);
transition: transform .25s ease, background-color .25s ease, color .25s ease, box-shadow .25s ease;
}
.jt-btn-light:hover,
.jt-btn-light:focus-visible {
background: var(--jt-btn-primary) !important;
border-color: var(--jt-btn-primary) !important;
color: #fff !important;
transform: translateY(-1px) scale(1.04);
box-shadow: 0 6px 20px rgba(246,121,56,.35) !important;
}
.jt-btn-primary {
background-image: linear-gradient(135deg, rgba(255,255,255,.22), rgba(255,255,255,0));
border: 1px solid rgba(255,255,255,.35);
box-shadow: 0 6px 18px rgba(246,121,56,.30) !important;
transition: transform .25s ease, box-shadow .25s ease, background-color .25s ease;
}
.jt-btn-primary:hover { transform: translateY(-1px); box-shadow: 0 10px 26px rgba(246,121,56,.45) !important; }

/* B8. Forms */
.form-control {
background: var(--glass-bg-soft) !important;
border: 1px solid var(--glass-border) !important;
border-radius: var(--glass-radius-sm);
color: inherit;
}
#search-header .form-control { border: 0 !important; }

/* B9. Footer */
#footer {
background: linear-gradient(180deg, rgba(33,37,41,.70), rgba(33,37,41,.92));
-webkit-backdrop-filter: var(--glass-filter);
backdrop-filter: var(--glass-filter);
border-top: 1px solid rgba(255,255,255,.12);
}
#socket {
background: rgba(9,8,12,.78);
-webkit-backdrop-filter: blur(10px);
backdrop-filter: blur(10px);
}
.dark-mode #footer { background: linear-gradient(180deg, rgba(24,24,29,.65), rgba(18,18,22,.92)); }

/* B10. Reusable content blocks for static pages / posts */
.glass-grid {
display: grid;
grid-template-columns: repeat(auto-fit, minmax(230px, 1fr));
gap: 1rem;
margin: 1.5rem 0;
}
.glass-box { padding: 1.1rem 1.25rem; margin: 1.25rem 0; }
.glass-box h3 { padding-top: 0 !important; margin-bottom: .5rem; }
.glass-box p:last-child { margin-bottom: 0; }
.key-takeaways {
padding: 1rem 1.25rem;
margin: 0 0 1.5rem;
border-left: 5px solid var(--jt-primary) !important;
border-radius: 0 var(--glass-radius-sm) var(--glass-radius-sm) 0 !important;
}
.key-takeaways strong { display: block; margin-bottom: .35rem; color: var(--jt-heading-color); }
.key-takeaways p { margin: 0; }
.entry-text details {
background: var(--glass-bg-soft);
border: 1px solid var(--glass-border);
border-radius: var(--glass-radius-sm);
padding: .75rem 1rem;
margin-bottom: .75rem;
}
.entry-text details summary { cursor: pointer; font-weight: 700; }
.entry-text dl dt { font-weight: 700; margin-top: .75rem; color: var(--jt-heading-color); }
.entry-text dl dd { margin: 0 0 .5rem; }

/* B11. AdSense-safe ad zones (reserved space = no layout shift) */
.ad-slot {
display: block;
position: relative;
margin: 1.5rem auto;
min-height: 280px;
max-width: 100%;
overflow: hidden;
text-align: center;
contain: layout;
border-radius: var(--glass-radius-sm);
}
.ad-slot::before {
content: "Advertisement";
display: block;
font-size: 11px;
line-height: 1.6;
opacity: .65;
letter-spacing: .02em;
}
.ad-slot.ad-header,
.ad-slot.ad-footer { min-height: 120px; }
.ad-slot.ad-sidebar { min-height: 270px; }
.ad-slot ins.adsbygoogle { display: block; min-height: inherit; }
/* keep ads away from buttons and nav (no accidental-click zones) */
.ad-slot { margin-top: 2rem; margin-bottom: 2rem; }
#sidebar .ad-slot { margin-top: 0; }

/* B12. Cookie notice */
.glass-cookie {
position: fixed;
left: 50%;
bottom: 16px;
transform: translateX(-50%);
z-index: 10000;
width: min(680px, calc(100% - 24px));
padding: 14px 18px;
display: flex;
flex-wrap: wrap;
align-items: center;
gap: 12px;
background: var(--glass-bg-strong);
-webkit-backdrop-filter: var(--glass-filter);
backdrop-filter: var(--glass-filter);
border: 1px solid var(--glass-border);
border-radius: var(--glass-radius);
box-shadow: var(--glass-shadow);
font-size: 14px;
}
.glass-cookie[hidden] { display: none; }
.glass-cookie p { margin: 0; flex: 1 1 260px; }

/* B13. Accessibility */
.skip-link {
position: absolute;
left: 12px;
top: -60px;
z-index: 100000;
padding: 10px 16px;
background: var(--jt-primary);
color: #fff;
border-radius: 999px;
}
.skip-link:focus { top: 12px; color: #fff; }
a:focus-visible,
button:focus-visible,
input:focus-visible,
textarea:focus-visible,
label:focus-visible,
summary:focus-visible {
outline: 3px solid var(--jt-primary);
outline-offset: 2px;
border-radius: 6px;
}
@media (prefers-reduced-motion: reduce) {
*, *::before, *::after {
animation-duration: .01ms !important;
transition-duration: .01ms !important;
scroll-behavior: auto !important;
}
.bg-archive:hover { transform: none; }
}
@media (prefers-contrast: more) {
:root { --glass-bg: rgba(255,255,255,.92); }
.dark-mode { --glass-bg: rgba(20,20,24,.94); }
}

/* B14. Responsive */
@media (max-width: 991.98px) {
#navbar {
background: var(--glass-bg-strong) !important;
-webkit-backdrop-filter: blur(20px) saturate(180%);
backdrop-filter: blur(20px) saturate(180%);
}
#sidebar { padding-top: 1rem; }
}
@media (max-width: 575.98px) {
:root { --glass-radius: 16px; }
#single-content, #page-content { padding: 1rem; }
.bg-archive:hover { transform: none; }
.ad-slot { min-height: 250px; }
}
@media print {
#header, #sidebar, #footer, .ad-slot, .glass-cookie, #back-to-top { display: none !important; }
body { background: #fff !important; }
}

/*Your custom CSS is here*/

/* ======================================================
   B16. Mobile menu + search open states, share bar, comments
   Self-contained: works even if the theme's own JS never loads.
   ====================================================== */
#search-header { position: relative; }
#search-header.search-open .dropdown-menu,
#search-header #search-toggle:checked ~ .dropdown-menu { display: block !important; }
#search-header .dropdown-menu {
right: 0;
left: auto;
min-width: min(92vw, 340px);
z-index: 10050;
}
#search-toggler[aria-expanded="true"] { color: var(--jt-primary); }
@media (max-width: 991.98px) {
#navbar { display: none; }
#navbar.is-open { display: block; }
body.nav-open { overflow: hidden; }
#navbar.is-open { max-height: calc(100vh - 80px); overflow-y: auto; }
}
/* Share bar */
.post-share {
display: flex;
align-items: center;
gap: .5rem;
flex-wrap: wrap;
margin: 0 0 1.5rem;
padding: .7rem .9rem;
border-radius: 18px;
}
.post-share-label {
font-size: .78rem;
font-weight: 800;
letter-spacing: .08em;
text-transform: uppercase;
opacity: .7;
margin-right: .15rem;
}
.post-share a,
.post-share button {
display: inline-flex;
align-items: center;
justify-content: center;
width: 38px;
height: 38px;
border-radius: 12px;
border: 1px solid var(--glass-border);
background: var(--glass-bg-soft);
color: inherit;
text-decoration: none;
cursor: pointer;
transition: transform .18s ease, background .18s ease, color .18s ease, border-color .18s ease;
}
.post-share svg { width: 19px; height: 19px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
.post-share a:hover, .post-share button:hover { transform: translateY(-2px); background: var(--jt-primary); border-color: var(--jt-primary); color: #fff; }
.post-share .share-btn.copied { background: #16a34a; border-color: #16a34a; color: #fff; }
/* Comments */
.comments { margin-top: 1.5rem; padding: 1.25rem; }
.comments-title { font-size: 1.15rem; font-weight: 800; margin: 0 0 .9rem; }
.comment { padding: .85rem 0; border-bottom: 1px solid var(--glass-border); }
.comment:last-child { border-bottom: 0; }
.comment-head { display: flex; align-items: baseline; gap: .6rem; flex-wrap: wrap; font-weight: 700; font-size: .92rem; }
.comment-head a { color: inherit; text-decoration: none; }
.comment-head a:hover { color: var(--jt-primary); }
.comment-time { font-weight: 400; font-size: .76rem; opacity: .68; }
.comment-body { margin-top: .35rem; font-size: .95rem; line-height: 1.65; }
.comment-form-wrap { margin-top: 1rem; }
.blogger-comment-form { width: 100%; border: 0; border-radius: 14px; background: transparent; }
.comment-hint { font-size: .9rem; opacity: .8; }

/* ======================================================
   B15. CRYSTAL GLASSMORPHISM — hover / specular layer
   Brighter rim + inset top highlight + sheen sweep on hover.
   Reuses the existing --glass-* tokens, changes no brand colour.
   ====================================================== */
:root {
--crystal-rim: rgba(255,255,255,.88);
--crystal-inset: inset 0 1px 0 rgba(255,255,255,.78);
--crystal-inset-bottom: inset 0 -1px 0 rgba(255,255,255,.06);
--crystal-lift: 0 20px 48px rgba(0,0,0,.18), 0 8px 26px rgba(246,121,56,.26);
--crystal-filter: blur(22px) saturate(185%);
--crystal-sheen: linear-gradient(115deg, rgba(255,255,255,.44) 0%, rgba(255,255,255,.12) 24%, rgba(255,255,255,0) 46%);
}
.dark-mode {
--crystal-rim: rgba(255,255,255,.26);
--crystal-inset: inset 0 1px 0 rgba(255,255,255,.18);
--crystal-lift: 0 22px 50px rgba(0,0,0,.55), 0 8px 26px rgba(246,121,56,.34);
--crystal-sheen: linear-gradient(115deg, rgba(255,255,255,.26) 0%, rgba(255,255,255,.07) 24%, rgba(255,255,255,0) 46%);
}
.glass,
.glass-box,
.bg-archive,
#sidebar .widget,
#single-content,
#page-content,
#toc-post,
.comments,
.post-author,
.accordion-item,
.key-takeaways,
.tp-card,
.tp-steps li {
position: relative;
border-color: var(--crystal-rim) !important;
box-shadow: var(--crystal-inset), var(--crystal-inset-bottom), var(--glass-shadow);
-webkit-backdrop-filter: var(--crystal-filter);
backdrop-filter: var(--crystal-filter);
transition: transform .3s cubic-bezier(.2,.7,.3,1), box-shadow .3s ease, border-color .3s ease, background-color .3s ease;
}
.bg-archive::after,
#sidebar .widget::after,
.glass::after,
.glass-box::after,
.tp-card::after {
content: "";
position: absolute;
inset: -1px;
border-radius: inherit;
pointer-events: none;
opacity: 0;
background: var(--crystal-sheen);
transition: opacity .35s ease;
}
.bg-archive:hover::after,
#sidebar .widget:hover::after,
.glass:hover::after,
.glass-box:hover::after,
.tp-card:hover::after {
opacity: 1;
}
.bg-archive:hover,
.tp-card:hover,
.glass:hover,
.glass-box:hover {
transform: translateY(-5px) scale(1.012);
border-color: var(--crystal-rim) !important;
box-shadow: var(--crystal-inset), var(--crystal-lift);
}
#sidebar .widget:hover {
transform: translateY(-3px);
border-color: var(--crystal-rim) !important;
box-shadow: var(--crystal-inset), var(--glass-shadow-hover);
}
.bg-archive:hover .item-thumbnail img {
transform: scale(1.05);
}
#navbar .menu-item > .nav-link {
transition: background-color .25s ease, color .25s ease, box-shadow .25s ease, transform .25s ease;
}
#navbar .navbar-nav > .menu-item > .nav-link:hover {
background: var(--glass-bg-soft);
box-shadow: var(--crystal-inset);
border-radius: 999px;
transform: translateY(-1px);
}
.btn,
.tp-go,
.tp-chip {
transition: transform .2s ease, box-shadow .2s ease, filter .2s ease, border-color .2s ease;
}
.btn:hover,
.tp-go:hover {
transform: translateY(-2px);
filter: brightness(1.05);
border-color: var(--crystal-rim) !important;
box-shadow: var(--crystal-inset), 0 12px 30px rgba(246,121,56,.34) !important;
}
/* B15.1 Shop cart icon (glass) */
.icobtn,
.cart-btn {
position: relative;
display: inline-flex;
align-items: center;
justify-content: center;
width: 42px;
height: 42px;
margin-left: .35rem;
border-radius: 14px;
text-decoration: none !important;
color: var(--jt-header-color);
background: linear-gradient(150deg, rgba(255,255,255,.34), rgba(255,255,255,.08));
border: 1px solid var(--crystal-rim);
-webkit-backdrop-filter: var(--crystal-filter);
backdrop-filter: var(--crystal-filter);
box-shadow: var(--crystal-inset), 0 6px 18px rgba(0,0,0,.12);
transition: transform .2s ease, box-shadow .2s ease, border-color .2s ease, color .2s ease;
}
.dark-mode .icobtn,
.dark-mode .cart-btn {
background: linear-gradient(150deg, rgba(255,255,255,.14), rgba(255,255,255,.04));
}
.icobtn svg,
.cart-btn svg {
width: 20px;
height: 20px;
fill: none;
stroke: currentColor;
stroke-width: 1.8;
stroke-linecap: round;
stroke-linejoin: round;
}
.icobtn:hover,
.cart-btn:hover {
transform: translateY(-3px) scale(1.05);
color: var(--jt-primary);
border-color: var(--jt-primary);
box-shadow: var(--crystal-inset), 0 12px 28px rgba(246,121,56,.34);
}
.cart-badge {
position: absolute;
top: -6px;
right: -6px;
min-width: 18px;
height: 18px;
padding: 0 4px;
border-radius: 999px;
background: var(--jt-primary);
color: #fff !important;
font-size: 10.5px;
font-weight: 800;
display: inline-flex;
align-items: center;
justify-content: center;
box-shadow: 0 3px 10px rgba(246,121,56,.5);
}
@media (max-width: 575px) {
.icobtn,
.cart-btn {
width: 38px;
height: 38px;
}
}
@media (prefers-reduced-motion: reduce) {
.bg-archive,
.tp-card,
.glass,
.glass-box,
#sidebar .widget,
.btn,
.tp-go,
.tp-chip,
.icobtn,
.cart-btn,
#navbar .menu-item > .nav-link {
transition: none !important;
}
.bg-archive:hover,
.tp-card:hover,
.glass:hover,
.glass-box:hover,
#sidebar .widget:hover,
.btn:hover,
.tp-go:hover,
.icobtn:hover,
.cart-btn:hover {
transform: none !important;
}
.bg-archive::after,
#sidebar .widget::after,
.glass::after,
.glass-box::after,
.tp-card::after {
display: none;
}
}

/* AIOU Coaching: lightweight responsive mobile navigation */
#aiou-share-sheet { display:none; position:fixed; z-index:10060; left:12px; right:12px; bottom:calc(86px + env(safe-area-inset-bottom)); padding:16px; gap:10px; flex-direction:column; border:1px solid rgba(120,120,120,.2); border-radius:18px; background:#fff; color:#252525; box-shadow:0 10px 35px rgba(0,0,0,.2); }
#aiou-share-sheet button, #aiou-share-sheet a { display:block; width:100%; padding:11px 13px; border:1px solid rgba(120,120,120,.18); border-radius:10px; background:transparent; color:inherit; text-align:left; font:600 14px system-ui,sans-serif; cursor:pointer; }
#aiou-share-sheet [data-aiou-share='close'] { width:34px; align-self:flex-end; text-align:center; padding:4px; font-size:20px; }
.dark-mode #aiou-share-sheet { background:#202328; color:#f5f5f5; border-color:rgba(255,255,255,.14); }
@media (min-width:992px) { #aiou-share-sheet { display:none !important; } }
#aiou-mobile-nav { display:none; }
@media (max-width: 991.98px) {
  body { padding-bottom:calc(74px + env(safe-area-inset-bottom)); }
  #aiou-mobile-nav {
    position:fixed; left:max(8px,env(safe-area-inset-left)); right:max(8px,env(safe-area-inset-right));
    bottom:calc(8px + env(safe-area-inset-bottom)); z-index:10050;
    display:grid; grid-template-columns:repeat(7,minmax(0,1fr)); gap:1px;
    padding:5px 4px; border:1px solid rgba(120,120,120,.13); border-radius:17px;
    background:rgba(255,255,255,.82); color:rgba(36,36,36,.86);
    box-shadow:0 3px 12px rgba(0,0,0,.08);
    contain:layout paint; -webkit-backface-visibility:hidden; backface-visibility:hidden;
  }
  #aiou-mobile-nav a, #aiou-mobile-nav button {
    min-width:0; min-height:46px; display:flex; flex-direction:column; align-items:center;
    justify-content:center; gap:2px; padding:3px 0; border:0; border-radius:11px;
    background:transparent; color:inherit; opacity:.84; text-decoration:none;
    font:600 10px/1.15 system-ui,-apple-system,sans-serif; white-space:nowrap;
    cursor:pointer; touch-action:manipulation; -webkit-tap-highlight-color:transparent;
  }
  #aiou-mobile-nav .aiou-nav-icon { width:22px; height:22px; fill:none; stroke:currentColor; stroke-width:1.9; stroke-linecap:round; stroke-linejoin:round; flex:none; color:#e66d2e; transition:transform .16s ease,color .16s ease; }
  #aiou-mobile-nav a:active, #aiou-mobile-nav button:active { background:rgba(230,109,46,.13); opacity:1; }
  #aiou-mobile-nav a:active .aiou-nav-icon, #aiou-mobile-nav button:active .aiou-nav-icon { transform:scale(.9); }
  #aiou-mobile-nav a:focus-visible, #aiou-mobile-nav button:focus-visible { outline:2px solid #e66d2e; outline-offset:1px; opacity:1; }
  #aiou-share-sheet { max-height: min(70vh, 420px); overflow:auto; gap:9px; }
  #aiou-share-sheet strong { font-size:16px; padding:3px 2px 7px; }
  #aiou-share-sheet button:active, #aiou-share-sheet a:active { background:rgba(230,109,46,.12); }
  body.dark-mode #aiou-mobile-nav, .dark-mode #aiou-mobile-nav, html[data-theme='dark'] #aiou-mobile-nav {
    background:rgba(28,30,34,.86); color:rgba(255,255,255,.9);
    border-color:rgba(255,255,255,.10); box-shadow:0 3px 12px rgba(0,0,0,.18);
  }
  #aiou-mobile-nav button:focus-visible, #aiou-mobile-nav a:focus-visible { outline:2px solid #e66d2e; outline-offset:1px; }
}
@media (max-width:380px) {
  #aiou-mobile-nav { left:5px; right:5px; gap:0; padding:4px 2px; border-radius:14px; }
  #aiou-mobile-nav a, #aiou-mobile-nav button { font-size:9px; min-height:44px; }
  #aiou-mobile-nav .aiou-nav-icon { width:19px; height:19px; }
}
@media (min-width: 992px) {
  body { padding-bottom:0 !important; }
  #aiou-mobile-nav { display:none !important; }
}

