/**/

/**/
(function () {
  'use strict';
  var nav = document.getElementById('navbar');
  var navCheck = document.getElementById('navbar-toggle');
  var searchWrap = document.getElementById('search-header');
  var searchCheck = document.getElementById('search-toggle');
  var searchInput = document.getElementById('search-input');

  function labels() { return document.querySelectorAll('label[for="navbar-toggle"]'); }

  function setMenu(open) {
    if (!nav) return;
    nav.classList.toggle('is-open', open);
    if (navCheck) navCheck.checked = open;
    document.body.classList.toggle('nav-open', open);
    Array.prototype.forEach.call(labels(), function (l) {
      l.setAttribute('aria-expanded', open ? 'true' : 'false');
    });
  }

  function setSearch(open) {
    if (!searchWrap) return;
    searchWrap.classList.toggle('search-open', open);
    if (searchCheck) searchCheck.checked = open;
    var t = document.getElementById('search-toggler');
    if (t) t.setAttribute('aria-expanded', open ? 'true' : 'false');
    if (open && searchInput) {
      try { searchInput.focus({ preventScroll: true }); } catch (err) { searchInput.focus(); }
    }
  }

  function closeAll() { setMenu(false); setSearch(false); }

  Array.prototype.forEach.call(labels(), function (label) {
    label.setAttribute('role', 'button');
    label.addEventListener('click', function (e) {
      e.preventDefault();
      e.stopPropagation();
      setMenu(!(nav && nav.classList.contains('is-open')));
    });
  });

  var searchToggler = document.getElementById('search-toggler');
  if (searchToggler) {
    searchToggler.setAttribute('role', 'button');
    searchToggler.addEventListener('click', function (e) {
      e.preventDefault();
      e.stopPropagation();
      setSearch(!(searchWrap && searchWrap.classList.contains('search-open')));
    });
  }

  if (nav) {
    nav.addEventListener('click', function (e) {
      if (e.target.closest && e.target.closest('a')) setMenu(false);
    });
  }

  document.addEventListener('click', function (e) {
    var t = e.target;
    if (nav && nav.classList.contains('is-open') && !nav.contains(t) &&
        !(t.closest && t.closest('label[for="navbar-toggle"]'))) setMenu(false);
    if (searchWrap && searchWrap.classList.contains('search-open') && !searchWrap.contains(t) &&
        !(t.closest && t.closest('#search-toggler'))) setSearch(false);
  });

  document.addEventListener('keydown', function (e) {
    if (e.key === 'Escape' || e.keyCode === 27) closeAll();
  });

  Array.prototype.forEach.call(document.querySelectorAll('.post-share'), function (bar) {
    var btn = bar.querySelector('.share-btn.copy');
    if (!btn) return;
    var url = bar.getAttribute('data-url') || location.href;
    btn.addEventListener('click', function () {
      var done = function () {
        btn.classList.add('copied');
        setTimeout(function () { btn.classList.remove('copied'); }, 1600);
      };
      if (navigator.clipboard && navigator.clipboard.writeText) {
        navigator.clipboard.writeText(url).then(done, function () {});
      }
    });
  });
})();
/**/

/**/
(function () {
  function ready(fn) {
    if (document.readyState !== 'loading') { fn(); } else { document.addEventListener('DOMContentLoaded', fn); }
  }

  /* 1. Quick answer: a 40-55 word direct answer taken from the first paragraph of a post.
        Skipped if the author already wrote a .key-takeaways block by hand. */
  ready(function () {
    try {
      var body = document.getElementById('post-body');
      if (!body || document.querySelector('.key-takeaways')) { return; }
      var first = body.querySelector('p');
      if (!first) { return; }
      var words = (first.textContent || '').replace(/\s+/g, ' ').trim().split(' ');
      if (words.length < 12) { return; }
      var box = document.createElement('div');
      box.className = 'key-takeaways';
      box.setAttribute('role', 'note');
      var title = document.createElement('strong');
      title.textContent = 'Quick answer';
      var text = document.createElement('p');
      text.textContent = words.slice(0, 55).join(' ') + (words.length > 55 ? '\u2026' : '');
      box.appendChild(title);
      box.appendChild(text);
      body.parentNode.insertBefore(box, body);
    } catch (e) {}
  });

  /* 2. Cookie notice (stores the choice in localStorage) */
  ready(function () {
    try {
      var bar = document.getElementById('cookie-consent');
      if (!bar) { return; }
      var saved = null;
      try { saved = localStorage.getItem('cookie-choice'); } catch (e) {}
      if (saved) { return; }
      bar.removeAttribute('hidden');
      function choose(value) {
        try { localStorage.setItem('cookie-choice', value); } catch (e) {}
        bar.setAttribute('hidden', 'hidden');
      }
      var yes = document.getElementById('cookie-accept');
      var no = document.getElementById('cookie-decline');
      if (yes) { yes.addEventListener('click', function () { choose('accepted'); }); }
      if (no) { no.addEventListener('click', function () { choose('declined'); }); }
    } catch (e) {}
  });
})();
/**/

/**/
(function () {
  var nav = document.getElementById('aiou-mobile-nav');
  if (!nav) return;
  var sheet = document.getElementById('aiou-share-sheet');
  var pageUrl = window.location.href.split('#')[0];
  var pageTitle = document.title || 'AIOU Coaching';

  function showShare() {
    if (!sheet) return;
    sheet.style.display = 'flex';
    sheet.setAttribute('aria-hidden', 'false');
    var wa = sheet.querySelector("[data-aiou-share='whatsapp']");
    if (wa) wa.href = 'https://wa.me/?text=' + encodeURIComponent(pageTitle + ' ' + pageUrl);
    var firstAction = sheet.querySelector("[data-aiou-share='native']");
    if (firstAction) firstAction.focus();
  }
  function hideShare() {
    if (!sheet) return;
    sheet.style.display = 'none';
    sheet.setAttribute('aria-hidden', 'true');
  }
  function copyPageLink(button) {
    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(pageUrl).then(function () {
        if (button) button.textContent = 'Link copied!';
      }).catch(function () { fallbackCopy(button); });
    } else {
      fallbackCopy(button);
    }
  }
  function fallbackCopy(button) {
    var field = document.createElement('textarea');
    field.value = pageUrl;
    field.setAttribute('readonly', 'readonly');
    field.style.position = 'fixed';
    field.style.opacity = '0';
    document.body.appendChild(field);
    field.select();
    try {
      var copied = document.execCommand('copy');
      if (button) button.textContent = copied ? 'Link copied!' : 'Select and copy the page URL';
    } catch (e) {
      if (button) button.textContent = 'Copy unavailable - use address bar';
    }
    document.body.removeChild(field);
  }

  nav.addEventListener('click', function (event) {
    var button = event.target.closest('[data-aiou-nav]');
    if (!button) return;
    var action = button.getAttribute('data-aiou-nav');

    if (action === 'search') {
      var searchToggle = document.getElementById('search-toggle');
      var searchLabel = document.getElementById('search-toggler');
      var searchInput = document.getElementById('search-input');
      if (searchToggle && !searchToggle.checked && searchLabel) searchLabel.click();
      window.requestAnimationFrame(function () {
        if (searchInput) {
          searchInput.focus();
          searchInput.scrollIntoView({ behavior: 'smooth', block: 'center' });
        }
      });
    } else if (action === 'menu') {
      var menuToggle = document.getElementById('navbar-toggle');
      var menuLabel = document.getElementById('navbar-toggler');
      if (menuToggle && menuLabel) menuLabel.click();
    } else if (action === 'comments') {
      var comments = document.getElementById('comments');
      var addComment = document.getElementById('add-comment');
      var commentButton = document.getElementById('comment-button');
      var destination = comments || addComment;
      if (destination) {
        destination.scrollIntoView({ behavior: 'smooth', block: 'start' });
        if (window.history && window.history.replaceState) {
          window.history.replaceState(null, '', '#comments');
        }
        if (comments) {
          comments.setAttribute('tabindex', '-1');
          window.setTimeout(function () { comments.focus({ preventScroll: true }); }, 350);
        } else if (commentButton) {
          commentButton.focus({ preventScroll: true });
        }
      } else {
        window.alert('Comments are available inside individual posts. Please open a post first.');
      }
    } else if (action === 'share') {
      showShare();
    } else if (action === 'dark') {
      var darkToggle = document.getElementById('dark-toggler');
      if (darkToggle) darkToggle.click();
    } else if (action === 'top') {
      window.scrollTo({ top: 0, behavior: 'smooth' });
    }
  });

  if (sheet) {
    sheet.addEventListener('click', function (event) {
      var action = event.target.closest('[data-aiou-share]');
      if (!action) {
        if (event.target === sheet) hideShare();
        return;
      }
      var type = action.getAttribute('data-aiou-share');
      if (type === 'close') hideShare();
      if (type === 'native') {
        if (navigator.share) {
          navigator.share({ title: pageTitle, text: pageTitle, url: pageUrl }).then(hideShare).catch(function () {});
        } else {
          copyPageLink(action);
        }
      }
      if (type === 'copy') copyPageLink(action);
    });
    document.addEventListener('keydown', function (event) {
      if (event.key === 'Escape' && sheet.getAttribute('aria-hidden') === 'false') hideShare();
    });
  }
})();;
 /**/
